mapper.sql:
WHERE 1=1
AND (UPPER(NVL(T1.OBJECT_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.OBJECT_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ASSET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')
AND T1.SOURCE_CD = #{sourceCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.SOURCE_CD AS SOURCE_CD, T1.OBJECT_ID AS OBJECT_ID, T1.OBJECT_NAME AS OBJECT_NAME,
           T1.ASSET_ID AS ASSET_ID, T1.EOL_DATE AS EOL_DATE
      FROM () T1

     ORDER BY T1.EOL_DATE ASC, T1.SOURCE_CD, T1.OBJECT_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}
